import{_ as s,a0 as a,w as p,s as l,ao as k,I as i,x as o,a1 as n,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Docker 在安全组件、实时容器迁移方面的进展 | LCTT x X-CMD","titleTemplate":false,"description":"Docker 在安全组件、实时容器迁移方面的进展 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Docker 在安全组件、实时容器迁移方面的进展 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Docker 在安全组件、实时容器迁移方面的进展 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150818 Docker Working on Security Components Live Container Migration","title":"Docker 在安全组件、实时容器迁移方面的进展","tag":"201509","desc":""},"relativePath":"201509/20150818 Docker Working on Security Components Live Container Migration.md","filePath":"[post].md"}'),c={name:"201509/20150818 Docker Working on Security Components Live Container Migration.md"};function D(T,e,m,C,u,d){const t=a("Link");return p(),l("div",null,[e[13]||(e[13]=k('<h1 id="docker-在安全组件、实时容器迁移方面的进展" tabindex="-1">Docker 在安全组件、实时容器迁移方面的进展 <a class="header-anchor" href="#docker-在安全组件、实时容器迁移方面的进展" aria-label="Permalink to “Docker 在安全组件、实时容器迁移方面的进展”">​</a></h1><p><img src="http://www.eweek.com/imagesvr_ce/1905/290x195DockerMarianna.jpg" alt="Docker Container Talk"></p><p><strong>这是 Docker 开发者在 Containercon 上的演讲，谈论将来的容器在安全和实时迁移方面的创新</strong></p><p>来自西雅图的消息。当前 IT 界最热的词汇是“容器”，美国有两大研讨会：Linuxcon USA 和 Containercon，后者就是为容器而生的。</p><p>Docker 公司是开源 Docker 项目的商业赞助商，本次研讨会这家公司有 3 位高管带来主题演讲，但公司创始人 Solomon Hykes 没上场演讲。</p><p>Hykes 曾在 2014 年的 Linuxcon 上进行过一次主题演讲，但今年的 Containeron 他只坐在观众席上。而工程部高级副总裁 Marianna Tessel、Docker 首席安全官 Diogo Monica 和核心维护员 Michael Crosby 为我们演讲 Docker 新增的功能和将来会有的功能。</p><p>Tessel 强调 Docker 现在已经被很多世界上大型组织用在生产环境中，包括美国政府。Docker 也被用在小环境中，比如树莓派，一块树莓派上可以跑 2300 个容器。</p><p>“Docker 的功能正在变得越来越强大，而部署方法变得越来越简单。”Tessel 在会上说道。</p><p>Tessel 把 Docker 形容成一艘游轮，内部由强大而复杂的机器驱动，外部为乘客提供平稳航行的体验。</p><p>Docker 试图解决的领域是简化安全配置。Tessel 认为对于大多数用户和组织来说，避免网络漏洞所涉及的安全问题是一个乏味而且复杂的过程。</p><p>于是 Docker Content Trust 就出现在 Docker 1.8 release 版本中了。安全项目领导 Diogo Mónica 中加入了 Tessel 的台上讨论，说安全是一个难题，而 Docker Content Trust 就是为解决这个难道而存在的。</p><p>Docker Content Trust 提供一种方法来验证一个 Docker 应用是否可信，以及多种方法来限制欺骗和病毒注入。</p><p>为了证明他的观点，Monica 做了个现场示范，演示 Content Trust 的效果。在一个实验中，一个网站在更新过程中其 Web App 被人为攻破，而当 Content Trust 启动后，这个黑客行为再也无法得逞。</p><p>“不要被这个表面上简单的演示欺骗了，”Tessel 说道，“你们看的是最安全的可行方案。”</p><p>Docker 以前没有实现的领域是实时迁移，这个技术在 VMware 虚拟机中叫做 vMotion，而现在，Docker 也实现了这个功能。</p><p>Docker 首席维护员 Micheal Crosby 在台上做了个实时迁移的演示，Crosby 把这个过程称为快照和恢复：首先从运行中的容器拿到一个快照，之后将这个快照移到另一个地方恢复。</p><p>一个容器也可以克隆到另一个地方，Crosby 将他的克隆容器称为“多利”，就是世界上第一只被克隆出来的羊的名字。</p><p>Tessel 也花了点时间聊了下 RunC 组件，这是个正在被 Open Container Initiative 作为多方开发的项目，目的是让它可以从 Linux 扩展到包括 Windows 和 Solaris 在内的多种操作系统。</p><p>Tessel 总结说她不知道 Docker 的未来是什么样，但对此抱非常乐观的态度。</p><p>“我不确定未来是什么样的，但我很确定 Docker 会在这个世界中脱颖而出”，Tessel 说的。</p><p>Sean Michael Kerner 是 eWEEK 和 InternetNews.com 网站的高级编辑，可通过推特 @TechJournalist 关注他。</p><hr>',22)),i("p",null,[e[1]||(e[1]=o("via: ",-1)),n(t,{href:"http://www.eweek.com/virtualization/docker-working-on-security-components-live-container-migration.html"},{default:r(()=>[...e[0]||(e[0]=[o("http://www.eweek.com/virtualization/docker-working-on-security-components-live-container-migration.html",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=o("作者：",-1)),n(t,{href:"http://www.eweek.com/cp/bio/Sean-Michael-Kerner/"},{default:r(()=>[...e[2]||(e[2]=[o("Sean Michael Kerner",-1)])]),_:1}),e[6]||(e[6]=o(" 译者：",-1)),n(t,{href:"https://github.com/bazz2"},{default:r(()=>[...e[3]||(e[3]=[o("bazz2",-1)])]),_:1}),e[7]||(e[7]=o(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=o("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原创翻译，",-1)),n(t,{href:"https://linux.cn/"},{default:r(()=>[...e[9]||(e[9]=[o("Linux中国",-1)])]),_:1}),e[12]||(e[12]=o(" 荣誉推出",-1))])])}const M=s(c,[["render",D]]);export{f as __pageData,M as default};
